16	// 用量导入文件（CSV，UTF-8，首行为固定表头，之后每行一条用量）：
17	//
18	//	usage_id,customer_id,time,quantity
19	//	u-001,cust-1,2026-09-15T10:00:00Z,100
20	//
21	//	usage_id   全局唯一用量标识，非空
22	//	customer_id 必须是已登记的客户标识
23	//	time       RFC3339 时间，如 2026-09-15T10:00:00Z 或 2026-09-15T18:00:00+08:00
24	//	quantity   正整数数量（有符号 64 位整数范围内）
25	const usageHeader = "usage_id,customer_id,time,quantity"
