27	// runCmd 解析并执行子命令。业务/用法错误通过 error 返回，由 main 统一
28	// 写入标准错误并以非零状态退出。
29	func runCmd(args []string, dataDir string) error {
30		switch args[0] {
31		case "customer":
32			if len(args) < 2 {
33				return usageError("缺少子命令，应为：customer add <标识> <名称> <单价分> 或 customer add-plan <标识> <名称> <方案标识>")
34			}
35			switch args[1] {
36			case "add":
37				if len(args) != 5 {
38					return usageError("用法：customer add <标识> <名称> <单价分>")
39				}
40				return cmdCustomerAdd(dataDir, args[2], args[3], args[4])
41			case "add-plan":
42				if len(args) != 5 {
43					return usageError("用法：customer add-plan <标识> <名称> <方案标识>")
44				}
45				return cmdCustomerAddPlan(dataDir, args[2], args[3], args[4])
46			default:
47				return usageError("未知 customer 子命令 %q；可用：add、add-plan", args[1])
48			}
49	
50		case "plan":
51			if len(args) < 2 {
52				return usageError("缺少子命令，应为：plan add|show|list|change|schedule ...")
53			}
54			switch args[1] {
55			case "add":
56				if len(args) < 5 {
57					return usageError("用法：plan add <标识> <名称> <上限:单价分>... <-:单价分>")
58				}
59				return cmdPlanAdd(dataDir, args[2], args[3], args[4:])
60			case "show":
61				if len(args) != 3 {
62					return usageError("用法：plan show <标识>")
63				}
64				return cmdPlanShow(dataDir, args[2])
65			case "list":
66				if len(args) != 2 {
67					return usageError("用法：plan list")
68				}
69				return cmdPlanList(dataDir)
70			case "change":
71				if len(args) != 6 {
72					return usageError("用法：plan change <客户标识> <YYYY-MM> <方案标识> <原因>")
73				}
74				return cmdPlanChange(dataDir, args[2], args[3], args[4], args[5])
75			case "schedule":
76				if len(args) != 3 && len(args) != 4 {
77					return usageError("用法：plan schedule <客户标识> [YYYY-MM]")
78				}
79				month, hasMonth := "", false
80				if len(args) == 4 {
81					month, hasMonth = args[3], true
82				}
83				return cmdPlanSchedule(dataDir, args[2], month, hasMonth)
84			default:
85				return usageError("未知 plan 子命令 %q；可用：add、show、list、change、schedule", args[1])
86			}
87	
88		case "usage":
89			if len(args) < 2 {
90				return usageError("缺少子命令，应为：usage import <文件>")
91			}
92			switch args[1] {
93			case "import":
94				if len(args) != 3 {
95					return usageError("用法：usage import <文件>（- 表示标准输入）")
96				}
97				return cmdUsageImport(dataDir, args[2])
98			default:
99				return usageError("未知 usage 子命令 %q；可用：import", args[1])
100			}
101	
102		case "bill":
103			if len(args) < 2 {
104				return usageError("缺少子命令，应为：bill settle|show|adjust|revoke|pay|remit|correct|unpay|ledger ...")
105			}
106			switch args[1] {
107			case "settle":
108				if len(args) != 4 {
109					return usageError("用法：bill settle <客户标识> <YYYY-MM>")
110				}
111				return cmdBillSettle(dataDir, args[2], args[3])
112			case "show":
113				if len(args) != 4 {
114					return usageError("用法：bill show <客户标识> <YYYY-MM>")
115				}
116				return cmdBillShow(dataDir, args[2], args[3])
117			case "adjust":
118				if len(args) != 7 {
119					return usageError("用法：bill adjust <客户标识> <YYYY-MM> <调整标识> <金额分> <原因>")
