135				}
136				return cmdBillRemit(dataDir, args[2], args[3], args[4], args[5], args[6:])
137			case "correct":
138				if len(args) < 6 {
139					return usageError("用法：bill correct <收款标识> <更正标识> <原因> <YYYY-MM:金额分> [更多 月份:金额 ...]")
140				}
141				return cmdBillCorrect(dataDir, args[2], args[3], args[4], args[5:])
142			case "unpay":
143				if len(args) != 4 {
144					return usageError("用法：bill unpay <收款标识> <原因>")
145				}
146				return cmdBillUnpay(dataDir, args[2], args[3])
147			case "ledger":
148				if len(args) != 4 && len(args) != 5 {
149					return usageError("用法：bill ledger <客户标识> <YYYY-MM> [截止操作序号]")
150				}
151				cutoff, hasCutoff := "", false
152				if len(args) == 5 {
153					cutoff, hasCutoff = args[4], true
154				}
155				return cmdBillLedger(dataDir, args[2], args[3], cutoff, hasCutoff)
156			default:
157				return usageError("未知 bill 子命令 %q；可用：settle、show、adjust、revoke、pay、remit、correct、unpay、ledger", args[1])
158			}
159	
160		default:
161			return usageError("未知命令 %q；可用：customer、plan、usage、bill", args[0])
162		}
163	}
