173	func cmdCustomerAdd(dir, id, name, priceText string) error {
174		if strings.TrimSpace(id) == "" {
175			return fmt.Errorf("客户标识不能为空")
176		}
177		if strings.TrimSpace(name) == "" {
178			return fmt.Errorf("客户名称不能为空")
179		}
180		price, err := parsePrice(priceText)
181		if err != nil {
182			return err
183		}
184	
185		s, err := loadStore(dir)
186		if err != nil {
187			return err
188		}
189		if _, exists := s.Customers[id]; exists {
190			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
191		}
192		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
193		if err := s.save(); err != nil {
194			return err
195		}
196		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
197		return nil
198	}
