219	func cmdUsageImport(dir, file string) error {
220		var reader io.ReadCloser
221		var source string
222		if file == "-" {
223			reader = io.NopCloser(os.Stdin)
224			source = "标准输入"
225		} else {
226			f, err := os.Open(file)
227			if err != nil {
228				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
229			}
230			reader = f
231			source = file
232		}
233		defer reader.Close()
234	
235		rows, parseErrs := parseUsageFile(reader)
236	
237		s, err := loadStore(dir)
238		if err != nil {
239			return err
240		}
241	
242		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
243		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
244		var problems []string
245		problems = append(problems, parseErrs...)
246	
247		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
248		var ordered []*parsedRow
249		newCount, dupCount := 0, 0
250	
251		for _, r := range rows {
252			cust, ok := s.Customers[r.rec.CustomerID]
253			if !ok {
254				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
255				continue
256			}
257			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
258			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
259			// 溢出（金额单位：分）。
260			if cust.PlanID == "" {
261				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
262					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
263					continue
264				}
265			} else {
266				rec := r.rec
267				month := r.t.UTC().Format("2006-01")
268				planID := s.effectivePlanID(cust, month)
269				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
270					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, month, planID, err))
271					continue
272				}
273			}
274	
275			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
276			var existing *usageRecord
277			if inStore, ok := s.Usage[r.rec.ID]; ok {
278				existing = inStore
279			} else if inBatch, ok := accepted[r.rec.ID]; ok {
280				existing = &inBatch.rec
281			}
282	
283			if existing != nil {
284				if !sameUsage(existing, &r.rec, r.t) {
285					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
286						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
287					continue
288				}
289				dupCount++
290				continue
291			}
292	
293			// 全新标识：不得进入该客户已封账的 UTC 自然月。
294			month := r.t.UTC().Format("2006-01")
295			if s.sealed(r.rec.CustomerID, month) {
296				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
297					r.line, r.rec.CustomerID, month, r.rec.ID))
298				continue
299			}
300	
301			rr := r
302			accepted[r.rec.ID] = rr
303			ordered = append(ordered, rr)
304			newCount++
305		}
306	
307		if len(problems) > 0 {
308			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
309		}
310	
311		for _, r := range ordered {
312			rec := r.rec
313			s.Usage[rec.ID] = &rec
314		}
315		if err := s.save(); err != nil {
316			return err
317		}
318		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
319		return nil
320	}
