322	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
323	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
324		cr := csv.NewReader(r)
325		cr.FieldsPerRecord = 4
326		cr.TrimLeadingSpace = true
327	
328		header, err := cr.Read()
329		if err == io.EOF {
330			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
331		}
332		if err != nil {
333			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
334		}
335		for i := range header {
336			header[i] = strings.TrimSpace(header[i])
337		}
338		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
339			header[2] != "time" || header[3] != "quantity" {
340			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
341		}
342	
343		var rows []*parsedRow
344		var problems []string
345		line := 1
346		for {
347			rec, err := cr.Read()
348			if err == io.EOF {
349				break
350			}
351			line++
352			if err != nil {
353				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
354				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
355					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
356					break
357				}
358				continue
359			}
360			for i := range rec {
361				rec[i] = strings.TrimSpace(rec[i])
362			}
363	
364			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
365			if id == "" {
366				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
367				continue
368			}
369			if custID == "" {
370				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
371				continue
372			}
373			t, err := time.Parse(time.RFC3339, ts)
374			if err != nil {
375				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
376				continue
377			}
378			qty, err := strconv.ParseInt(qtyText, 10, 64)
379			if err != nil {
380				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
381				continue
382			}
383			if qty <= 0 {
384				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
385				continue
386			}
387	
388			rows = append(rows, &parsedRow{
389				line: line,
390				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
391				t:    t,
392			})
393		}
394		return rows, problems
395	}
396	
397	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
398	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
399	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
400		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
401			return false
402		}
403		et, err := time.Parse(time.RFC3339, existing.Time)
404		if err != nil {
405			return existing.Time == candidate.Time
406		}
407		return et.Equal(candidateT)
408	}
409	
410	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
411	func validMonth(m string) bool {
412		t, err := time.Parse("2006-01", m)
413		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
414			return false
415		}
416		return true
417	}
418	
419	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
420	func inMonth(rfc3339, month string) bool {
421		t, err := time.Parse(time.RFC3339, rfc3339)
422		if err != nil {
423			return false
424		}
425		return t.UTC().Format("2006-01") == month
426	}
427	
428	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
429	// 入参时间均已在载入/导入时校验为 RFC3339。
430	func utcMonth(rfc3339 string) string {
431		t, _ := time.Parse(time.RFC3339, rfc3339)
432		return t.UTC().Format("2006-01")
433	}
