558	func printBill(b *bill, cust *customer, s *state) {
559		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
560		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
561		// 涉及该月即纳入，即使后来被更正移出。
562		pays := paymentsEverFor(s, b.CustomerID, b.Month)
563		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
564		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
565		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
566		tiered := b.Pricing == "tiered"
567		if tiered {
568			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
569			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
570			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
571			fmt.Fprintln(stdout, "阶梯规则：")
572			for i, t := range b.PlanTiers {
573				if t.Limit == 0 {
574					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
575				} else {
