664	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
665	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
666	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
667	// 的最新分配。
668	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
669		type event struct {
670			seq  int64
671			text string
672		}
673		var events []event
674		for _, p := range pays {
675			alloc := p.amountFor(month)
676			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
677				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
678			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
679			running := alloc
680			for _, c := range correctionsFor(s, p.ID) {
681				after := allocAmountFor(c.Allocations, month)
682				if running == 0 && after == 0 {
683					continue // 本次更正不涉及本账单
684				}
685				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
686					c.ID, c.Reason, p.ID, running, after)})
687				running = after
688			}
689			if p.Revoked {
690				// 整笔撤销取消的是撤销时的最新分配。
691				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
692					p.ID, p.RevokeReason, p.ID, p.Total, running)})
693			}
694		}
695		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
696		out := make([]string, len(events))
697		for i, ev := range events {
698			out[i] = ev.text
699		}
700		return out
701	}
