811	func cmdBillRevoke(dir, adjID, reason string) error {
812		if strings.TrimSpace(adjID) == "" {
813			return fmt.Errorf("调整标识不能为空")
814		}
815		if strings.TrimSpace(reason) == "" {
816			return fmt.Errorf("撤销原因不能为空")
817		}
818	
819		s, err := loadStore(dir)
820		if err != nil {
821			return err
822		}
823		a, ok := s.Adjustments[adjID]
824		if !ok {
825			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
826		}
827	
828		if a.Revoked {
829			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
830			// 改用其他原因则拒绝。
831			if a.RevokeReason == reason {
832				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
833				printAdjustment(a, s)
834				return nil
835			}
836			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
837		}
838	
839		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
840		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
841		// 改变余额后重试。
842		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
843		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
844		if err != nil {
845			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
846		}
847		received, err := paymentReceived(s, a.CustomerID, a.Month)
848		if err != nil {
849			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
850		}
851		neg, err := neg64(a.Amount)
852		if err != nil {
853			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
854		}
855		newPayable, err := addSigned64(payable, neg)
856		if err != nil {
857			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
858				payable, a.Amount)
859		}
860		if newPayable < 0 {
861			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
862				newPayable, payable, a.Amount)
863		}
864		if newPayable < received {
865			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
866				newPayable, received, payable, a.Amount)
867		}
868	
869		a.Revoked = true
870		a.RevokeReason = reason
871		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
872		s.NextSeq++
873		a.RevokeSeq = s.NextSeq
874	
875		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
876		if err := s.save(); err != nil {
877			a.Revoked = false
878			a.RevokeReason = ""
879			a.RevokedAt = ""
880			a.RevokeSeq = 0
881			s.NextSeq--
882			return err
883		}
884		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
885			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
886		printAdjustment(a, s)
887		return nil
888	}
