890	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
891	func printAdjustment(a *adjustment, s *state) {
892		b := s.Bills[billKey(a.CustomerID, a.Month)]
893		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
894		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
895		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
896		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
897		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
898		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
899		if a.Revoked {
900			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
901		} else {
902			fmt.Fprintf(stdout, "当前状态：生效中\n")
903		}
904		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
905	}
