920	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
921		if !validMonth(month) {
922			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
923		}
924		amount, err := parsePositiveAmount(amountText)
925		if err != nil {
926			return err
927		}
928		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
929		return registerPayment(dir, customerID, payID, amount, note,
930			[]paymentAllocation{{Month: month, Amount: amount}})
931	}
