933	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
934		total, err := parsePositiveAmount(totalText)
935		if err != nil {
936			return err
937		}
938		allocs, err := parseAllocations(allocArgs)
939		if err != nil {
940			return err
941		}
942		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
943		var sum int64
944		for _, al := range allocs {
945			sum, err = add64(sum, al.Amount)
946			if err != nil {
947				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
948			}
949		}
950		if sum != total {
951			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
952		}
953		return registerPayment(dir, customerID, payID, total, note, allocs)
954	}
