956	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
957	// 月份不得重复，每项金额为正整数分。
958	func parseAllocations(args []string) ([]paymentAllocation, error) {
959		if len(args) == 0 {
960			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
961		}
962		seen := make(map[string]bool)
963		allocs := make([]paymentAllocation, 0, len(args))
964		for _, arg := range args {
965			parts := strings.Split(arg, ":")
966			if len(parts) != 2 {
967				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
968			}
969			month := strings.TrimSpace(parts[0])
970			if !validMonth(month) {
971				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
972			}
973			if seen[month] {
974				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
975			}
976			seen[month] = true
977			amount, err := parsePositiveAmount(parts[1])
978			if err != nil {
979				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
980			}
981			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
982		}
983		return allocs, nil
984	}
