986	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
987	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
988	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
989		if strings.TrimSpace(payID) == "" {
990			return fmt.Errorf("收款标识不能为空")
991		}
992		if strings.TrimSpace(note) == "" {
993			return fmt.Errorf("收款备注不能为空")
994		}
995		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
996		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
997	
998		s, err := loadStore(dir)
999		if err != nil {
1000			return err
1001		}
1002		if _, ok := s.Customers[customerID]; !ok {
1003			return fmt.Errorf("客户标识 %q 不存在", customerID)
1004		}
1005		for _, al := range allocs {
1006			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1007				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1008			}
1009		}
1010	
1011		if existing, ok := s.Payments[payID]; ok {
1012			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1013			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1014			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1015			if samePaymentContent(existing, customerID, total, note, allocs) {
1016				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1017				printPayment(existing, s)
1018				return nil
1019			}
1020			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1021				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1022		}
1023	
1024		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1025		for _, al := range allocs {
1026			b := s.Bills[billKey(customerID, al.Month)]
1027			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1028			if err != nil {
1029				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1030			}
1031			received, err := paymentReceived(s, customerID, al.Month)
1032			if err != nil {
1033				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1034			}
1035			if payable == 0 {
1036				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1037			}
1038			if al.Amount > payable-received {
1039				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1040					al.Amount, payable-received, customerID, al.Month, payable, received)
1041			}
1042		}
1043	
1044		p := &payment{
1045			ID:          payID,
1046			CustomerID:  customerID,
1047			Total:       total,
1048			Note:        note,
1049			Allocations: allocs,
1050			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1051		}
1052		s.NextSeq++
1053		p.Seq = s.NextSeq
1054		s.Payments[payID] = p
1055	
1056		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1057		// 一切不生效，该收款标识不被占用。
1058		if err := s.save(); err != nil {
1059			delete(s.Payments, payID)
1060			s.NextSeq--
1061			return err
1062		}
1063		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1064		printAllocationBalances(s, p, allocs)
1065		fmt.Fprintln(stdout)
1066		printPayment(p, s)
1067		return nil
1068	}
1069	
1070	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1071	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1072	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1073		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1074			return false
1075		}
1076		return sameAllocations(p.Allocations, allocs)
1077	}
1078	
1079	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1080	func sameAllocations(a, b []paymentAllocation) bool {
1081		if len(a) != len(b) {
1082			return false
1083		}
1084		for _, al := range b {
1085			if allocAmountFor(a, al.Month) != al.Amount {
1086				return false
1087			}
1088		}
1089		return true
1090	}
1091	
1092	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1093	func formatAllocations(allocs []paymentAllocation) string {
1094		parts := make([]string, len(allocs))
1095		for i, al := range allocs {
1096			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1097		}
1098		return strings.Join(parts, ",")
1099	}
