1112	func cmdBillUnpay(dir, payID, reason string) error {
1113		if strings.TrimSpace(payID) == "" {
1114			return fmt.Errorf("收款标识不能为空")
1115		}
1116		if strings.TrimSpace(reason) == "" {
1117			return fmt.Errorf("撤销原因不能为空")
1118		}
1119	
1120		s, err := loadStore(dir)
1121		if err != nil {
1122			return err
1123		}
1124		p, ok := s.Payments[payID]
1125		if !ok {
1126			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1127		}
1128	
1129		if p.Revoked {
1130			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1131			// 改用其他原因则拒绝。
1132			if p.RevokeReason == reason {
1133				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1134				printPayment(p, s)
1135				return nil
1136			}
1137			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1138		}
1139	
1140		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1141		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1142		// 分配、更正与撤销原因永久保留。
1143		p.Revoked = true
1144		p.RevokeReason = reason
1145		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1146		s.NextSeq++
1147		p.RevokeSeq = s.NextSeq
1148	
1149		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1150		if err := s.save(); err != nil {
1151			p.Revoked = false
1152			p.RevokeReason = ""
1153			p.RevokedAt = ""
1154			p.RevokeSeq = 0
1155			s.NextSeq--
1156			return err
1157		}
1158		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1159		printAllocationBalances(s, p, currentAllocations(s, p))
1160		fmt.Fprintln(stdout)
1161		printPayment(p, s)
1162		return nil
1163	}
