1192	// --- 收款分配更正 ---
1193	
1194	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1195		if strings.TrimSpace(payID) == "" {
1196			return fmt.Errorf("收款标识不能为空")
1197		}
1198		if strings.TrimSpace(corrID) == "" {
1199			return fmt.Errorf("更正标识不能为空")
1200		}
1201		if strings.TrimSpace(reason) == "" {
1202			return fmt.Errorf("更正原因不能为空")
1203		}
1204		allocs, err := parseAllocations(allocArgs)
1205		if err != nil {
1206			return err
1207		}
1208		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1209		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1210	
1211		s, err := loadStore(dir)
1212		if err != nil {
1213			return err
1214		}
1215		p, ok := s.Payments[payID]
1216		if !ok {
1217			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1218		}
1219	
1220		if existing, ok := s.Corrections[corrID]; ok {
1221			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1222			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1223			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1224			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1225				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1226				printCorrection(existing, s)
1227				return nil
1228			}
1229			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1230				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1231		}
1232	
1233		// 新增更正只允许未撤销收款。
1234		if p.Revoked {
1235			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1236		}
1237	
1238		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1239		var sum int64
1240		for _, al := range allocs {
1241			sum, err = add64(sum, al.Amount)
1242			if err != nil {
1243				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1244			}
1245		}
1246		if sum != p.Total {
1247			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1248		}
1249		// 新分配月份须是原客户的已结算账单。
1250		for _, al := range allocs {
1251			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1252				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1253			}
1254		}
1255	
1256		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1257		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1258		current := currentAllocations(s, p)
1259		for _, m := range unionMonths(current, allocs) {
1260			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1261			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1262			if err != nil {
1263				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1264			}
1265			received, err := paymentReceived(s, p.CustomerID, m)
1266			if err != nil {
1267				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1268			}
1269			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1270			received -= allocAmountFor(current, m)
1271			received, err = add64(received, allocAmountFor(allocs, m))
1272			if err != nil {
1273				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1274			}
1275			if received > payable {
1276				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1277					p.CustomerID, m, received, payable)
1278			}
1279		}
1280	
1281		c := &correction{
1282			ID:          corrID,
1283			PaymentID:   payID,
1284			Reason:      reason,
1285			Allocations: allocs,
1286			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1287		}
1288		s.NextSeq++
1289		c.Seq = s.NextSeq
1290		s.Corrections[corrID] = c
1291	
1292		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1293		// 一切不生效，该更正标识不被占用。
1294		if err := s.save(); err != nil {
1295			delete(s.Corrections, corrID)
1296			s.NextSeq--
1297			return err
1298		}
1299		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1300		printCorrection(c, s)
1301		return nil
1302	}
1303	
1304	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1305	func unionMonths(a, b []paymentAllocation) []string {
1306		set := make(map[string]bool, len(a)+len(b))
1307		for _, al := range a {
1308			set[al.Month] = true
1309		}
1310		for _, al := range b {
1311			set[al.Month] = true
1312		}
1313		months := make([]string, 0, len(set))
1314		for m := range set {
1315			months = append(months, m)
1316		}
1317		sort.Strings(months)
1318		return months
1319	}
1320	
1321	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1322	// 新分配，或（首次更正时）收款的原始分配。
1323	func allocationBefore(s *state, c *correction) []paymentAllocation {
1324		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1325		var latest *correction
1326		for _, o := range s.Corrections {
1327			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1328				latest = o
1329			}
1330		}
1331		if latest != nil {
1332			before = latest.Allocations
1333		}
1334		return before
1335	}
1336	
1337	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1338	// 以及前后分配涉及月份的当前余额。
1339	func printCorrection(c *correction, s *state) {
1340		p := s.Payments[c.PaymentID] // 载入时已校验存在
1341		before := allocationBefore(s, c)
1342		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1343		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1344			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1345		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1346		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1347		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1348		fmt.Fprintln(stdout, "涉及月份当前余额：")
1349		for _, m := range unionMonths(before, c.Allocations) {
1350			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1351			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1352			received, _ := paymentReceived(s, p.CustomerID, m)
1353			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1354				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1355				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1356		}
1357	}
1358	
1359	// --- 账后对账流水 ---
1360	
1361	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1362	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1363	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1364	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1365	type ledgerEvent struct {
1366		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1367		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1368		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1369		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1370		deltaReceived int64  // 对实收的影响（分，带符号）
1371		note          string // 原因（调整/更正类）或备注（收款类）
1372		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1373		payTotal      int64  // 收款类事件：汇款总额
1374		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1375		payID         string // 更正事件：关联收款标识
1376		beforeAlloc   int64  // 更正事件：本账单更正前分配
1377		afterAlloc    int64  // 更正事件：本账单更正后分配
1378		afterPayable  int64  // 事件后的应付（回放时填充）
1379		afterReceived int64  // 事件后的实收（回放时填充）
1380	}
1381	
1382	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1383	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1384	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1385	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1386	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1387	// 只读：不修改库、不占用序号、不新增记录。
1388	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1389		var events []ledgerEvent
1390		for _, a := range s.Adjustments {
1391			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1392				continue
1393			}
1394			events = append(events, ledgerEvent{
1395				seq: a.Seq, kind: "调整", refID: a.ID,
1396				deltaPayable: a.Amount, note: a.Reason,
1397			})
1398			if a.Revoked {
1399				neg, err := neg64(a.Amount)
1400				if err != nil {
1401					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1402				}
1403				events = append(events, ledgerEvent{
1404					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1405					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1406				})
1407			}
1408		}
1409		for _, p := range s.Payments {
1410			if p.CustomerID != b.CustomerID {
1411				continue
1412			}
1413			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1414			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1415			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1416			alloc := p.amountFor(b.Month)
1417			corrs := correctionsFor(s, p.ID)
1418			involved := alloc > 0
1419			if !involved {
1420				for _, c := range corrs {
1421					if allocAmountFor(c.Allocations, b.Month) > 0 {
1422						involved = true
1423						break
1424					}
1425				}
1426			}
1427			if !involved {
1428				continue
1429			}
1430			if alloc > 0 {
1431				events = append(events, ledgerEvent{
1432					seq: p.Seq, kind: "收款", refID: p.ID,
1433					deltaReceived: alloc, note: p.Note,
1434					payTotal: p.Total, payAlloc: alloc,
1435				})
1436			}
1437			running := alloc
1438			for _, c := range corrs {
1439				after := allocAmountFor(c.Allocations, b.Month)
1440				if running == 0 && after == 0 {
1441					continue // 本次更正不涉及本账单
1442				}
1443				events = append(events, ledgerEvent{
1444					seq: c.Seq, kind: "更正", refID: c.ID,
1445					deltaReceived: after - running, note: c.Reason,
1446					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1447				})
1448				running = after
1449			}
1450			if p.Revoked {
1451				events = append(events, ledgerEvent{
1452					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1453					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1454					payTotal: p.Total, payAlloc: running,
1455				})
1456			}
1457		}
1458		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1459	
1460		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1461		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1462		// 仍能成功。
1463		payable := b.TotalFee
1464		var received int64
1465		seen := make(map[int64]string, len(events))
1466		for i := range events {
1467			ev := &events[i]
1468			desc := ev.kind + " " + ev.refID
1469			if prev, dup := seen[ev.seq]; dup {
1470				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1471			}
1472			seen[ev.seq] = desc
1473			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1474				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1475			}
1476			var err error
1477			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1478				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1479			}
1480			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1481				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1482			}
1483			if payable < 0 {
1484				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1485			}
1486			if received < 0 {
1487				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1488			}
1489			if received > payable {
1490				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1491			}
1492			ev.afterPayable = payable
1493			ev.afterReceived = received
1494		}
1495		return events, nil
1496	}
1497	
1498	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1499		if !validMonth(month) {
1500			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1501		}
1502		s, err := loadStore(dir)
1503		if err != nil {
1504			return err
1505		}
1506		cust, ok := s.Customers[customerID]
1507		if !ok {
1508			return fmt.Errorf("客户标识 %q 不存在", customerID)
1509		}
1510		b, ok := s.Bills[billKey(customerID, month)]
1511		if !ok {
1512			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1513		}
1514	
1515		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1516		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1517		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1518		cutoff := s.NextSeq
1519		cutoffDesc := "省略，按最新"
1520		if hasCutoff {
1521			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1522			if perr != nil {
1523				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1524			}
1525			if v < 0 {
1526				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1527			}
1528			if v > s.NextSeq {
1529				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1530			}
1531			cutoff = v
1532			cutoffDesc = "指定"
1533		}
1534	
1535		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1536		// 拒绝，不输出部分正常的报告。
1537		events, err := billLedger(s, b)
1538		if err != nil {
1539			return err
1540		}
1541		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1542		return nil
1543	}
1544	
1545	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1546		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1547		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1548		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1549		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1550		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1551		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1552		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1553			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1554	
1555		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1556		payable, received := b.TotalFee, int64(0)
1557		var shown []ledgerEvent
1558		for _, ev := range events {
1559			if ev.seq > cutoff {
1560				continue
1561			}
1562			shown = append(shown, ev)
1563			payable, received = ev.afterPayable, ev.afterReceived
1564		}
1565		if len(shown) == 0 {
1566			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1567		} else {
1568			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1569			for i, ev := range shown {
1570				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1571			}
1572		}
1573		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1574			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1575	}
1576	
1577	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1578	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1579	// 说明汇款总额与本账单分配。
1580	func formatLedgerEvent(ev ledgerEvent) string {
1581		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1582			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1583		switch ev.kind {
1584		case "调整":
1585			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1586				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1587		case "撤销调整":
1588			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1589				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1590		case "收款":
1591			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1592				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1593		case "更正":
1594			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1595				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1596		default: // 撤销收款
1597			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1598				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1599		}
1600	}
1601

