169		Reason      string              `json:"reason"`
170		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
171		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
172		CreatedAt   string              `json:"created_at"`
173	}
174	
175	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
176	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
177	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
178	type planChange struct {
179		CustomerID string `json:"customer_id"`
180		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
181		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
182		Reason     string `json:"reason"`
183		CreatedAt  string `json:"created_at"`
184	}
185	
186	type state struct {
187		Version     int                     `json:"version"`
188		Customers   map[string]*customer    `json:"customers"`
189		Plans       map[string]*plan        `json:"plans"`        // 全局唯一方案标识 -> 阶梯计费方案
190		Usage       map[string]*usageRecord `json:"usage"`        // 全局唯一用量标识 -> 记录
191		Bills       map[string]*bill        `json:"bills"`        // 客户 + "|" + 月份 -> 账单
192		Adjustments map[string]*adjustment  `json:"adjustments"`  // 全局唯一调整标识 -> 记录
193		Payments    map[string]*payment     `json:"payments"`     // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
194		Corrections map[string]*correction  `json:"corrections"`  // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
195		PlanChanges map[string]*planChange  `json:"plan_changes"` // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写）
196		NextSeq     int64                   `json:"next_seq"`     // 已分配的最大操作序号（调整/收款/更正及其撤销共用；方案变更不占用）
197		path        string                  `json:"-"`
198	}
199	
200	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
201	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
202	func loadStore(dir string) (*state, error) {
203		p := filepath.Join(dir, "state.json")
204		data, err := os.ReadFile(p)
205		if err != nil {
206			if errors.Is(err, os.ErrNotExist) {
207				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
208					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
209				}
210				return newState(p), nil
211			}
212			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
213		}
214	
215		var s state
216		dec := json.NewDecoder(bytes.NewReader(data))
217		if err := dec.Decode(&s); err != nil {
218			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
219		}
220		// 拒绝尾部多余内容，避免静默吞掉异常数据。
221		if dec.More() {
222			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
223		}
224		if err := s.validate(); err != nil {
225			return nil, fmt.Errorf("数据文件已损坏: %w", err)
226		}
227		// 旧版本数据文件没有 plans/adjustments/payments/corrections/plan_changes/
228		// next_seq 字段：视为零方案、零调整、零实收、零更正、零方案变更。
229		if s.Plans == nil {
230			s.Plans = map[string]*plan{}
231		}
232		if s.Adjustments == nil {
233			s.Adjustments = map[string]*adjustment{}
234		}
235		if s.Payments == nil {
236			s.Payments = map[string]*payment{}
237		}
238		if s.Corrections == nil {
239			s.Corrections = map[string]*correction{}
240		}
241		if s.PlanChanges == nil {
242			s.PlanChanges = map[string]*planChange{}
243		}
244		s.path = p
245		return &s, nil
246	}
247	
248	func newState(p string) *state {
249		return &state{
250			Version:     stateVersion,
251			Customers:   map[string]*customer{},
252			Plans:       map[string]*plan{},
253			Usage:       map[string]*usageRecord{},
254			Bills:       map[string]*bill{},
255			Adjustments: map[string]*adjustment{},
256			Payments:    map[string]*payment{},
257			Corrections: map[string]*correction{},
258			PlanChanges: map[string]*planChange{},
259			path:        p,
260		}
261	}
